insert into public.ifund_demo_campaigns(id,owner_id,title,summary,story,category,goal_cents,status,organizer,location,latitude,longitude)
select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,title,summary,story,category,goal,'published',organizer,location,lat,lon
from (values
 (1,'A safe landing for the residents of Halcyon Court','Help fictional neighbors replace essential supplies after a synthetic apartment emergency.',
 '[{"heading":"A sudden change of orbit","text":"Halcyon Court is a fictional apartment community. In this demonstration story, an electrical fire has displaced several invented households. Mira Sol, a synthetic resident organizer, is coordinating a short-term response so neighbors have a place to rest and a way to replace everyday essentials."},{"heading":"A practical first week","text":"The fictional plan budgets for temporary accommodation, clean clothing, grocery vouchers and replacement school supplies. A small volunteer team would publish an itemized summary and offer residents choices about what they need. The goal is a bridge toward stability, without making promises about individual outcomes."},{"heading":"What your support demonstrates","text":"A PayPal Sandbox contribution demonstrates the verified donation and receipt process. No real household receives funds, and no real emergency is represented. Every person, place and circumstance in this campaign is fictional."}]'::jsonb,
 'emergency',650000,'Mira Sol (fictional)','Halcyon Court (synthetic)',40.1,-73.9),
 (2,'One steady step for Luma’s recovery','A fictional recovery fund for accessible transport, home adaptations and time to heal.',
 '[{"heading":"Room for recovery","text":"Luma Vale is a fictional adult in a synthetic coastal town. This demonstration story explores the practical costs that can surround recovery after an injury: transport, accessibility equipment and reduced work hours. It does not describe a real patient or make a medical claim."},{"heading":"A clear plan for everyday needs","text":"The fictional organizer would use this fund for an accessible taxi allowance, temporary mobility equipment and modest home adaptations. A published budget would separate those practical expenses and be updated as needs change. Support is framed as assistance with daily life, never a guarantee of treatment or recovery."},{"heading":"A safe way to explore giving","text":"This campaign lets judges see how a sensitive story can remain clear and compassionate while fictional identities protect real people. Sandbox contributions test the accounting path only. No medical services are purchased and no real funds move."}]'::jsonb,
 'medical',1800000,'Elio Vale (fictional)','Tideglass Bay (synthetic)',-33.4,18.5),
 (3,'Reopen the doors of Aurora Harbor’s learning center','Restore a fictional neighborhood’s shared library, quiet study spaces and community workshops.',
 '[{"heading":"A place to learn together","text":"Aurora Harbor is a fictional neighborhood whose shared learning center has been damaged in a synthetic storm. The invented center gives residents a quiet place to study and a shelf of books to explore. This story imagines how a community could organize a transparent rebuilding effort."},{"heading":"Books, desks and a brighter room","text":"The fictional budget includes replacing water-damaged books, repairing study tables, improving lighting and purchasing accessible learning materials. Volunteer workshop sessions would help residents practice digital skills. The project would share progress updates and an itemized spending plan before any real-world fundraising were considered."},{"heading":"An invitation to possibility","text":"The goal is a welcoming place for curiosity to grow. Here, a sandbox donation demonstrates that a contribution can be verified and recorded without presenting synthetic activity as a real fundraiser. Every organizer and location is fictional."}]'::jsonb,
 'education',1200000,'Nova Reed (fictional)','Aurora Harbor (synthetic)',37.3,-121.8),
 (4,'Clean water after the Silverwind storm','A fictional disaster-response project supplying portable filters and safe collection containers.',
 '[{"heading":"After the rain","text":"Silverwind District is a synthetic location used to explore community disaster relief. In this fictional scenario, a severe storm has interrupted neighborhood water access. An invented volunteer group is preparing a practical distribution plan while making clear that it represents no real disaster or affected community."},{"heading":"Small supplies, organized carefully","text":"The fictional budget covers portable filtration kits, clean collection containers, delivery coordination and clear multilingual instruction cards. A distribution log would count supplies rather than make unsupported claims about people helped. Community feedback would guide later changes to the plan."},{"heading":"Test the response without real funds","text":"This campaign is a safe demonstration of how a relief story, discovery listing and verified sandbox receipt can connect. It is not an appeal on behalf of a real emergency. No live donations, purchases or payouts occur."}]'::jsonb,
 'disaster_relief',2500000,'Tessa Quill (fictional)','Silverwind District (synthetic)',14.5,121.1),
 (5,'A little garden for a whole neighborhood','Transform a fictional unused courtyard into an accessible garden and shared gathering space.',
 '[{"heading":"A space between buildings","text":"The invented residents of Meridian Commons imagine a courtyard where people can meet, grow herbs and share a quiet afternoon. Today, in this fictional story, the space is bare and difficult to access. A synthetic neighborhood group wants to turn a modest shared idea into a practical community project."},{"heading":"Build the useful things first","text":"The fictional plan begins with accessible paths, raised planting beds, rain barrels and durable seating. Volunteers would choose plants suited to the imagined climate and publish a simple maintenance rota. The budget includes replacement materials so the space can remain useful after the first planting day."},{"heading":"A shared place to begin","text":"In the demo, sandbox contributions show how a community campaign can record support transparently. This is synthetic content, not verified local organizing. The courtyard, residents and organizer are fictional, and no real funds are collected."}]'::jsonb,
 'community',800000,'Arden Moss (fictional)','Meridian Commons (synthetic)',51.4,-.2),
 (6,'A softer landing for the animals of Comet Haven','A fictional animal-welfare fund for safe enclosures, supplies and volunteer training.',
 '[{"heading":"Care needs a safe place","text":"Comet Haven is an invented animal-welfare group in a synthetic town. Its fictional volunteers are preparing temporary spaces for animals awaiting placement. This demonstration avoids using images or stories of identifiable real animals, shelters or beneficiaries."},{"heading":"Comfort, routine and preparation","text":"The fictional budget covers washable bedding, secure enclosures, feed storage and introductory volunteer training. The plan focuses on practical care conditions rather than promising adoption outcomes. An itemized update would explain what was purchased and what still needs attention."},{"heading":"Explore the contribution trail","text":"A sandbox donation demonstrates a verifiable contribution and a clear receipt. It does not provide veterinary care or finance a real shelter. The campaign, organizer and location are fictional, and no actual payouts are available."}]'::jsonb,
 'animals',950000,'Rin Calder (fictional)','Comet Haven (synthetic)',-37.7,145.1),
 (7,'Give the Ember Estuary room to breathe','Equip a fictional coastal volunteer group for shoreline cleanups and habitat observation.',
 '[{"heading":"A shoreline worth noticing","text":"Ember Estuary is a synthetic coastline imagined for this environmental demonstration. A fictional volunteer group wants to remove litter from public paths and observe habitat changes responsibly. No real conservation project, environmental measurement or verified impact is represented."},{"heading":"Useful equipment and careful records","text":"The fictional plan includes reusable collection tools, sorting stations, safety equipment and basic observation notebooks. Volunteers would record the type and weight of collected material rather than make broad ecological claims. A small reserve would maintain equipment for later cleanup days."},{"heading":"Make the record as clear as the goal","text":"This campaign connects a hopeful fictional story with sandbox-only financial records. Judges can inspect the donation purpose and capture reference without mistaking demonstration totals for real conservation funding. Every place and identity is invented."}]'::jsonb,
 'environment',700000,'Sora Flint (fictional)','Ember Estuary (synthetic)',-12.2,-77.1),
 (8,'Draw a new world in the Starlight mural studio','A fictional community art project turning shared stories into a colorful public mural.',
 '[{"heading":"Stories deserve a wall","text":"The Starlight mural studio is a fictional collective of artists in an invented district. Its demonstration project imagines a mural shaped by neighborhood stories and workshop sketches. The campaign uses no real artist’s identity or copyrighted character as a beneficiary."},{"heading":"Create together, document clearly","text":"The fictional budget includes wall preparation, weather-resistant paints, accessible workshop materials and a modest equipment allowance. Participants would agree on imagery and attribution before painting. Progress updates would show the process rather than promise a specific audience or commercial result."},{"heading":"From a sketch to a shared possibility","text":"Sandbox contributions demonstrate how creative projects can explain their plans and account for support. This mural will not be funded or built by the demo. Its story, organizer and location are synthetic, and no real money is transferred."}]'::jsonb,
 'creative',550000,'Cass Vega (fictional)','Starlight Quarter (synthetic)',48.7,2.2),
 (9,'Put a telescope in the hands of tomorrow’s explorers','Build a fictional neighborhood astronomy kit and a series of accessible night-sky workshops.',
 '[{"heading":"Curiosity starts with a question","text":"The fictional Orbit Classroom collective wants to make the night sky easier to explore. Its synthetic organizers imagine lending a small telescope kit and running beginner-friendly observing sessions. The campaign is an educational story, not a real mission, laboratory or space agency initiative."},{"heading":"Start small and share the view","text":"The fictional plan includes a portable telescope, a stable mount, printed sky guides and accessibility materials for indoor workshops. Volunteers would organize careful equipment handling and avoid promising specific viewing conditions. A shared logbook would record observations and questions for later sessions."},{"heading":"A universe of possibility","text":"The demo connects science-inspired campaign discovery with a genuine sandbox payment path when configured. Test contributions create no real research budget and no withdrawable balance. Every organizer, location and proposed activity is fictional."}]'::jsonb,
 'science',1500000,'Pax Orion (fictional)','Orbit Classroom (synthetic)',35.6,139.6)
